import sys

def can_partition_brute(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    n = len(nums)
    def dfs(i, cur):
        if cur == target:
            return True
        if i >= n or cur > target:
            return False
        return dfs(i + 1, cur + nums[i]) or dfs(i + 1, cur)
    return dfs(0, 0)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print('true' if can_partition_brute(nums) else 'false')

import sys

def can_partition_best(nums):
    total = sum(nums)
    if total % 2:
        return False
    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True
    for v in nums:
        for j in range(target, v - 1, -1):
            dp[j] = dp[j] or dp[j - v]
    return dp[target]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    nums = list(map(int, data[1:1 + n]))
    print('true' if can_partition_best(nums) else 'false')
